/* @lc app=leetcode id=3869 lang=kotlin */ class Solution { fun good(x: Int): Boolean = x.toString().zipWithNext().let { z -> z.all { it.first < it.second } || z.all { it.first > it.second } } fun go(ds: List<Int>, pos: Int, last: Int, inc: Boolean, dec: Boolean, sum: Int, tight: Boolean, started: Boolean, memo: HashMap<Int, Long>): Long = if (pos == ds.size) (if (started && (inc || dec || good(sum))) 1L else 0L) else memo.getOrPut(((((pos * 10 + last) * 2 + (if (inc) 1 else 0)) * 2 + (if (dec) 1 else 0)) * 140 + sum) * 4 + (if (tight) 2 else 0) + (if (started) 1 else 0)) { (0..(if (tight) ds[pos] else 9)).sumOf { d -> if (!started && d == 0) go(ds, pos + 1, 0, true, true, 0, tight && d == ds[pos], false, memo) else go(ds, pos + 1, d, if (started) inc && d > last else true, if (started) dec && d < last else true, sum + d, tight && d == ds[pos], true, memo) } } fun countFancy(l: Long, r: Long): Long = go(r.toString().map { it - '0' }, 0, 0, true, true, 0, true, false, HashMap()) - go((l - 1).toString().map { it - '0' }, 0, 0, true, true, 0, true, false, HashMap()) }